INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','present-perfect','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"present-perfect","title":"Present perfect: experience and results","level":"B1","order":29,"summary":"The present perfect connects earlier events with the present: an experience so far, a recent result or a period that is still open. Contrast this with a finished past time such as yesterday. A past participle may resemble the past simple, but irregular verbs can differ: went / gone, saw / seen.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Connect two points in time","Build the perfect verb","Negatives and questions","Time expressions and short answers"],"rules":[{"title":"Connect two points in time","explanation":"The present perfect connects earlier events with the present: an experience so far, a recent result or a period that is still open. Contrast this with a finished past time such as yesterday. A past participle may resemble the past simple, but irregular verbs can differ: went / gone, saw / seen.","pattern":"Subject + **have / has + past participle**","commonMistakes":["For a finished date, use past simple: I visited last year. British English often prefers present perfect with just or already; American English also uses past simple in those contexts."],"examples":["Use the present perfect: She **has prepared** the visitor guide up to now.","Use the present perfect: She **has restored** the old portrait up to now."],"skill":"form"},{"title":"Build the perfect verb","explanation":"A perfect construction uses **have as an auxiliary**, followed by a past participle. Regular participles normally end in -ed. Irregular ones must be learned with their base and past forms: write / wrote / written. Do not substitute an -ing form unless you also build the continuous construction.","pattern":"She **has written**. / They **have written**.","commonMistakes":["The form written is a participle; wrote is past simple. They are not interchangeable after have."],"examples":["Make a present-perfect negative: They **have not prepared** the visitor guide up to now.","Make a present-perfect negative: They **have not restored** the old portrait up to now."],"skill":"meaning"},{"title":"Negatives and questions","explanation":"Put **not after have or has**. For a yes/no question, move the auxiliary before the subject. The participle stays unchanged. There is no extra do or did because the perfect construction already contains an auxiliary.","pattern":"Have they finished? / They **have not finished**.","commonMistakes":["Do not combine did with a perfect auxiliary to make its negative or question."],"examples":["Begin this present-perfect question: **Have** they prepared the visitor guide up to now?","Begin this present-perfect question: **Have** they restored the old portrait up to now?"],"skill":"contrast"},{"title":"Time expressions and short answers","explanation":"Read the whole sentence to locate the reference time. Here it is **up to now**. Keep the appropriate form of have in a short answer and omit the repeated participle. Since names a starting point; for names a duration. Neither word automatically selects a single tense.","pattern":"Yes, they **have**. / No, they **have not**.","commonMistakes":["Been can describe a completed visit; gone often means the person has left and has not yet returned."],"examples":["Choose the participle for the present perfect: We have **prepared** the visitor guide up to now. (prepare)","Choose the participle for the present perfect: We have **restored** the old portrait up to now. (restore)"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"32138060-1773-5cc3-ac54-e4c84220140b","topicSlug":"present-perfect","level":"B1","prompt":"Use the present perfect: She ____ the visitor guide up to now.","choices":[{"id":"A","text":"has preparing"},{"id":"B","text":"has to prepare"},{"id":"C","text":"has been preparing"},{"id":"D","text":"has prepared"}],"answerId":"D","hint":"Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested present perfect needs **has + prepared** with she. The reference is up to now.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"present-perfect-1","fingerprint":"ff2b30b02373955c2a58315b029af5eb10c6a0ca06f5aaedd57bcea726b9595b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested present perfect needs **has + prepared** with she. The reference is up to now.","Choose **has prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect simple takes a past participle, not an -ing form.","B":"An infinitive cannot follow the perfect auxiliary here.","C":"This is a perfect continuous form; the instruction specifically asks for perfect simple.","D":"The requested present perfect needs **has + prepared** with she. The reference is up to now."}}},{"id":"a990ebf5-d64f-5909-a77c-a0eb6d8d0ca5","topicSlug":"present-perfect","level":"B1","prompt":"Make a present-perfect negative: They ____ the visitor guide up to now.","choices":[{"id":"A","text":"have not preparing"},{"id":"B","text":"not have prepared"},{"id":"C","text":"have not prepared"},{"id":"D","text":"did not have prepared"}],"answerId":"C","hint":"Keep the present-perfect auxiliary and add **not** immediately after it.","explanation":"Place **not after have** and keep **prepared**: they have not prepared.","keywords":["perfect-negative"],"skill":"perfect-negative","contextKey":"present-perfect-1","fingerprint":"f6f248aa9024f81545c15d0867c87fcd4affac068e37718a04215aca5d42c3c7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the present-perfect auxiliary and add **not** immediately after it.","Place **not after have** and keep **prepared**: they have not prepared.","Choose **have not prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The -ing form needs been for a perfect continuous, which is not requested.","B":"In the standard finite negative, not follows the auxiliary.","C":"Place **not after have** and keep **prepared**: they have not prepared.","D":"Perfect negatives do not add did; not follows the existing auxiliary."}}},{"id":"b086f612-238a-5aca-afe3-b2d0ceb879c2","topicSlug":"present-perfect","level":"B1","prompt":"Begin this present-perfect question: ____ they prepared the visitor guide up to now?","choices":[{"id":"A","text":"Are"},{"id":"B","text":"Has"},{"id":"C","text":"Have"},{"id":"D","text":"Did"}],"answerId":"C","hint":"The first auxiliary moves before the subject; do not add a new auxiliary.","explanation":"Move **have** before they. The participle prepared remains after the subject.","keywords":["perfect-question"],"skill":"perfect-question","contextKey":"present-perfect-1","fingerprint":"59f55ad379398fc47e22da5c0ea92a7880bf4a735183f7cf9246f5e7de5ebe97","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary moves before the subject; do not add a new auxiliary.","Move **have** before they. The participle prepared remains after the subject.","Choose **Have**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Are would create a different structure, not the requested perfect.","B":"Has does not agree with they, and cannot form a past-perfect question.","C":"Move **have** before they. The participle prepared remains after the subject.","D":"Did would require a base verb and would not make this perfect question."}}},{"id":"5787c6b6-0605-5f19-a313-8f1d4a624368","topicSlug":"present-perfect","level":"B1","prompt":"Choose the participle for the present perfect: We have ____ the visitor guide up to now. (prepare)","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"preparing"},{"id":"C","text":"to prepare"},{"id":"D","text":"been preparing"}],"answerId":"A","hint":"Identify the past participle, rather than choosing a word only because it looks past.","explanation":"The past participle of **prepare** is **prepared**. It follows have in the requested perfect construction.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"present-perfect-1","fingerprint":"e2f0d1ddb615c5079549404a22cb3aa794e9bffc879ad05ec77f3f78df1edfc9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the past participle, rather than choosing a word only because it looks past.","The past participle of **prepare** is **prepared**. It follows have in the requested perfect construction.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The past participle of **prepare** is **prepared**. It follows have in the requested perfect construction.","B":"This is the -ing form, not the past participle.","C":"This is the to-infinitive, not a past participle.","D":"This would make a perfect continuous construction, not perfect simple."}}},{"id":"46beccd7-5319-5534-a289-d4698372a454","topicSlug":"present-perfect","level":"B1","prompt":"Use the present perfect: She ____ the old portrait up to now.","choices":[{"id":"A","text":"has to restore"},{"id":"B","text":"has been restoring"},{"id":"C","text":"has restored"},{"id":"D","text":"has restoring"}],"answerId":"C","hint":"Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested present perfect needs **has + restored** with she. The reference is up to now.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"present-perfect-2","fingerprint":"7dba8565d60b2dea3935aa241a0756512dfa54adbf0ca8f47e1cd723a1be5ed7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested present perfect needs **has + restored** with she. The reference is up to now.","Choose **has restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An infinitive cannot follow the perfect auxiliary here.","B":"This is a perfect continuous form; the instruction specifically asks for perfect simple.","C":"The requested present perfect needs **has + restored** with she. The reference is up to now.","D":"The perfect simple takes a past participle, not an -ing form."}}},{"id":"c847e028-a848-53af-a20d-7cbbcb8c3bf9","topicSlug":"present-perfect","level":"B1","prompt":"Make a present-perfect negative: They ____ the old portrait up to now.","choices":[{"id":"A","text":"have not restored"},{"id":"B","text":"did not have restored"},{"id":"C","text":"have not restoring"},{"id":"D","text":"not have restored"}],"answerId":"A","hint":"Keep the present-perfect auxiliary and add **not** immediately after it.","explanation":"Place **not after have** and keep **restored**: they have not restored.","keywords":["perfect-negative"],"skill":"perfect-negative","contextKey":"present-perfect-2","fingerprint":"2a5bd949ae7bc8736c3a4b4a85e6fff413d61d6d1d086857040660f482607738","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the present-perfect auxiliary and add **not** immediately after it.","Place **not after have** and keep **restored**: they have not restored.","Choose **have not restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Place **not after have** and keep **restored**: they have not restored.","B":"Perfect negatives do not add did; not follows the existing auxiliary.","C":"The -ing form needs been for a perfect continuous, which is not requested.","D":"In the standard finite negative, not follows the auxiliary."}}},{"id":"3f10ef1f-ee27-526c-aaa3-fa00a1a69814","topicSlug":"present-perfect","level":"B1","prompt":"Begin this present-perfect question: ____ they restored the old portrait up to now?","choices":[{"id":"A","text":"Has"},{"id":"B","text":"Have"},{"id":"C","text":"Did"},{"id":"D","text":"Are"}],"answerId":"B","hint":"The first auxiliary moves before the subject; do not add a new auxiliary.","explanation":"Move **have** before they. The participle restored remains after the subject.","keywords":["perfect-question"],"skill":"perfect-question","contextKey":"present-perfect-2","fingerprint":"1cde1676f6abb6ad7ab4f5ccaeb091a80132a13fc6efc56fe15b1c29b2f11e03","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary moves before the subject; do not add a new auxiliary.","Move **have** before they. The participle restored remains after the subject.","Choose **Have**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Has does not agree with they, and cannot form a past-perfect question.","B":"Move **have** before they. The participle restored remains after the subject.","C":"Did would require a base verb and would not make this perfect question.","D":"Are would create a different structure, not the requested perfect."}}},{"id":"388bb63c-912b-5a2a-a898-69205bae4098","topicSlug":"present-perfect","level":"B1","prompt":"Choose the participle for the present perfect: We have ____ the old portrait up to now. (restore)","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"been restoring"},{"id":"C","text":"restored"},{"id":"D","text":"restoring"}],"answerId":"C","hint":"Identify the past participle, rather than choosing a word only because it looks past.","explanation":"The past participle of **restore** is **restored**. It follows have in the requested perfect construction.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"present-perfect-2","fingerprint":"4654b880420c578788fc929de99c7f20b54f4a8994774e1fee2cbf4829b94c0f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the past participle, rather than choosing a word only because it looks past.","The past participle of **restore** is **restored**. It follows have in the requested perfect construction.","Choose **restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the to-infinitive, not a past participle.","B":"This would make a perfect continuous construction, not perfect simple.","C":"The past participle of **restore** is **restored**. It follows have in the requested perfect construction.","D":"This is the -ing form, not the past participle."}}},{"id":"eb9412f5-7661-534b-a2e5-9bacbd8c2bc8","topicSlug":"present-perfect","level":"B1","prompt":"Use the present perfect: She ____ the garden fence up to now.","choices":[{"id":"A","text":"has measured"},{"id":"B","text":"has measuring"},{"id":"C","text":"has to measure"},{"id":"D","text":"has been measuring"}],"answerId":"A","hint":"Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested present perfect needs **has + measured** with she. The reference is up to now.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"present-perfect-3","fingerprint":"1c91b1f3915d718aaf9822734780d34dff116464ad42978fd0ff3d5e3122c5ba","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested present perfect needs **has + measured** with she. The reference is up to now.","Choose **has measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The requested present perfect needs **has + measured** with she. The reference is up to now.","B":"The perfect simple takes a past participle, not an -ing form.","C":"An infinitive cannot follow the perfect auxiliary here.","D":"This is a perfect continuous form; the instruction specifically asks for perfect simple."}}},{"id":"7340ff21-74f4-592e-aa8a-8aa1b2a56964","topicSlug":"present-perfect","level":"B1","prompt":"Make a present-perfect negative: They ____ the garden fence up to now.","choices":[{"id":"A","text":"have not measuring"},{"id":"B","text":"not have measured"},{"id":"C","text":"have not measured"},{"id":"D","text":"did not have measured"}],"answerId":"C","hint":"Keep the present-perfect auxiliary and add **not** immediately after it.","explanation":"Place **not after have** and keep **measured**: they have not measured.","keywords":["perfect-negative"],"skill":"perfect-negative","contextKey":"present-perfect-3","fingerprint":"0bf23fcbf5e28a328b0b6c4737fb2979fa08dfe91cd7b68d6ce758c2c303b147","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the present-perfect auxiliary and add **not** immediately after it.","Place **not after have** and keep **measured**: they have not measured.","Choose **have not measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The -ing form needs been for a perfect continuous, which is not requested.","B":"In the standard finite negative, not follows the auxiliary.","C":"Place **not after have** and keep **measured**: they have not measured.","D":"Perfect negatives do not add did; not follows the existing auxiliary."}}},{"id":"fcee81f3-2f83-5766-a1dc-d331bd9e9d79","topicSlug":"present-perfect","level":"B1","prompt":"Begin this present-perfect question: ____ they measured the garden fence up to now?","choices":[{"id":"A","text":"Did"},{"id":"B","text":"Are"},{"id":"C","text":"Has"},{"id":"D","text":"Have"}],"answerId":"D","hint":"The first auxiliary moves before the subject; do not add a new auxiliary.","explanation":"Move **have** before they. The participle measured remains after the subject.","keywords":["perfect-question"],"skill":"perfect-question","contextKey":"present-perfect-3","fingerprint":"9593eb55abbe4f97467d9f4af9a794433e0dd9a9a766b6d2ad4ac6378d7da573","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary moves before the subject; do not add a new auxiliary.","Move **have** before they. The participle measured remains after the subject.","Choose **Have**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did would require a base verb and would not make this perfect question.","B":"Are would create a different structure, not the requested perfect.","C":"Has does not agree with they, and cannot form a past-perfect question.","D":"Move **have** before they. The participle measured remains after the subject."}}},{"id":"efb3fe6e-c42d-510a-a2d4-74b92425bf00","topicSlug":"present-perfect","level":"B1","prompt":"Choose the participle for the present perfect: We have ____ the garden fence up to now. (measure)","choices":[{"id":"A","text":"to measure"},{"id":"B","text":"been measuring"},{"id":"C","text":"measured"},{"id":"D","text":"measuring"}],"answerId":"C","hint":"Identify the past participle, rather than choosing a word only because it looks past.","explanation":"The past participle of **measure** is **measured**. It follows have in the requested perfect construction.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"present-perfect-3","fingerprint":"9cc257eef5754c69b82449c7454924b534d7dfd65961113ea3f5417dd052ce27","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the past participle, rather than choosing a word only because it looks past.","The past participle of **measure** is **measured**. It follows have in the requested perfect construction.","Choose **measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the to-infinitive, not a past participle.","B":"This would make a perfect continuous construction, not perfect simple.","C":"The past participle of **measure** is **measured**. It follows have in the requested perfect construction.","D":"This is the -ing form, not the past participle."}}},{"id":"014fdeba-6472-5f1e-a372-866caea8ea51","topicSlug":"present-perfect","level":"B1","prompt":"Use the present perfect: She ____ the travel leaflet up to now.","choices":[{"id":"A","text":"has been translating"},{"id":"B","text":"has translated"},{"id":"C","text":"has translating"},{"id":"D","text":"has to translate"}],"answerId":"B","hint":"Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested present perfect needs **has + translated** with she. The reference is up to now.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"present-perfect-4","fingerprint":"a050e95d60478c3322f93a039a9a0a00b64c9d68fb8f121799d6e26b9e54afb2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the present reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested present perfect needs **has + translated** with she. The reference is up to now.","Choose **has translated**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is a perfect continuous form; the instruction specifically asks for perfect simple.","B":"The requested present perfect needs **has + translated** with she. The reference is up to now.","C":"The perfect si